package com.lmspilot.notification.api;
import com.lmspilot.notification.domain.*;import com.lmspilot.support.api.ApiException;import com.lmspilot.support.security.CurrentUser;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
record NotificationResponse(UUID id,String type,String title,String body,boolean read,Instant createdAt,Instant readAt){}record NotificationSummary(long unread,List<NotificationResponse> items){}record NotificationMessage(UUID userId,String type,String title,String body,Map<String,Object> variables){}
@Service @Transactional class NotificationService{private final NotificationRepository repo;NotificationService(NotificationRepository r){repo=r;}NotificationSummary mine(){UUID u=user();return new NotificationSummary(repo.countByUserIdAndChannelAndReadFalse(u,NotificationChannel.IN_APP),repo.findAllByUserIdAndChannelOrderByCreatedAtDesc(u,NotificationChannel.IN_APP).stream().limit(200).map(this::view).toList());}NotificationResponse read(UUID id){NotificationEntity e=repo.findById(id).orElseThrow(this::nf);if(!e.userId.equals(user()))throw new ApiException(HttpStatus.FORBIDDEN,"NOTIFICATION_OUT_OF_SCOPE","Không được đọc thông báo của người khác");e.read=true;e.readAt=Instant.now();e.updatedAt=e.readAt;return view(repo.save(e));}long readAll(){UUID u=user();List<NotificationEntity> list=repo.findAllByUserIdAndChannelOrderByCreatedAtDesc(u,NotificationChannel.IN_APP);Instant now=Instant.now();long n=0;for(NotificationEntity e:list)if(!e.read){e.read=true;e.readAt=now;e.updatedAt=now;n++;}repo.saveAll(list);return n;}NotificationResponse create(NotificationMessage m){NotificationEntity e=new NotificationEntity();e.userId=m.userId();e.type=m.type();e.title=m.title();e.body=m.body();return view(repo.save(e));}private NotificationResponse view(NotificationEntity e){return new NotificationResponse(e.id,e.type,e.title,e.body,e.read,e.createdAt,e.readAt);}private ApiException nf(){return new ApiException(HttpStatus.NOT_FOUND,"NOTIFICATION_NOT_FOUND","Không tìm thấy thông báo");}private UUID user(){try{return CurrentUser.id();}catch(Exception e){return new UUID(0,1);}}}
@RestController @RequestMapping("/api/v1/notifications") public class NotificationApi{private final NotificationService service;public NotificationApi(NotificationService s){service=s;}@GetMapping public NotificationSummary list(){return service.mine();}@PostMapping("/{id}/read") public NotificationResponse read(@PathVariable UUID id){return service.read(id);}@PostMapping("/read-all") public Map<String,Long> readAll(){return Map.of("updated",service.readAll());}}
